fn classify(n: i32) -> i32 {
    match n {
        100 => 0xffffff,
        0..=9 => 0x0000ff,
        10..50 => 0x00ff00,
        _ => 0xff0000,
    }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let band: i32 = h / 4;
    host::display::fill_rect(0, 0, w, band, classify(5));
    host::display::fill_rect(0, band, w, band, classify(20));
    host::display::fill_rect(0, band * 2, w, band, classify(100));
    host::display::fill_rect(0, band * 3, w, h - band * 3, classify(999));
    host::display::present();
}
